SELECT *
FROM AlertEvidence
WHERE FileName = 'winatp-intro-backdoor.exe'
   OR FileName LIKE '%winatp-intro-backdoor.exe%'
LIMIT 50;

SELECT *
FROM DeviceFileEvents
WHERE FileName = 'winatp-intro-backdoor.exe'
   OR FileName LIKE '%winatp-intro-backdoor.exe%'
LIMIT 50;
]

